class Distribution:
    """A scalar value or array values with associated uncertainty distribution.

    This object will take its exact type from whatever the ``samples``
    argument is. In general this is expected to be ``NdarrayDistribution`` for
    |ndarray| input, and, e.g., ``QuantityDistribution`` for a subclass such
    as |Quantity|. But anything compatible with `numpy.asanyarray` is possible
    (generally producing ``NdarrayDistribution``).

    See also: https://docs.astropy.org/en/stable/uncertainty/

    Parameters
    ----------
    samples : array-like
        The distribution, with sampling along the *trailing* axis. If 1D, the sole
        dimension is used as the sampling axis (i.e., it is a scalar distribution).
        If an |ndarray| or subclass, the data will not be copied unless it is not
        possible to take a view (generally, only when the strides of the last axis
        are negative).

    """

    _generated_subclasses = {}

    def __new__(cls, samples):
        if isinstance(samples, Distribution):
            samples = samples.distribution
        samples = np.asanyarray(samples)
        if samples.shape == ():
            raise TypeError("Attempted to initialize a Distribution with a scalar")

        samples_cls = samples.__class__
        if cls is Distribution:
            cls = cls._generated_subclasses.get(samples_cls)
            if cls is None:
                cls = type(
                    f"{samples_cls.__name__}Distribution",
                    (_DistributionRepr, ArrayDistribution, samples_cls),
                    {
                        "_samples_cls": samples_cls,
                        "__module__": Distribution.__module__,
                    },
                )
                Distribution._generated_subclasses[samples_cls] = cls

        n_samples = samples.shape[-1]
        sample_stride = samples.strides[-1]
        # A structured dtype can encode positive padding between samples.  It
        # cannot safely encode backwards or overlapping samples (except for a
        # single broadcast sample), so copy those layouts first.
        if sample_stride < samples.dtype.itemsize or (
            sample_stride == 0 and n_samples != 1
        ):
            samples = np.ascontiguousarray(samples)
            sample_stride = samples.strides[-1]
        if sample_stride == 0:  # one sample broadcast from a scalar
            sample_stride = samples.dtype.itemsize

        dtype = cls._get_distribution_dtype(
            samples.dtype, n_samples, itemsize=sample_stride
        )
        interface = samples.__array_interface__.copy()
        interface.update(
            shape=samples.shape[:-1],
            strides=samples.strides[:-1],
            typestr=dtype.str,
            descr=dtype.descr,
        )
        result = np.asarray(DummyArray(interface, base=samples)).view(cls)
        result.__array_finalize__(samples)
        return result

    @staticmethod
    def _get_distribution_dtype(dtype, n_samples, itemsize=None):
        dtype = np.dtype(dtype)
        base = dtype.base
        if itemsize is None:
            itemsize = base.itemsize
        if itemsize < base.itemsize:
            raise ValueError("sample stride is smaller than the sample dtype")
        sample_dtype = np.dtype(
            {
                "names": ["sample"],
                "formats": [base],
                "offsets": [0],
                "itemsize": itemsize,
            }
        )
        return np.dtype([("samples", sample_dtype, (n_samples,))])

    @property
    def n_samples(self):
        return super().dtype["samples"].shape[0]
    @property
    def distribution(self):
        return self["samples"]["sample"]

    @property
    def dtype(self):
        return super().dtype["samples"].base["sample"]

    @dtype.setter
    def dtype(self, dtype):
        dtype = self._get_distribution_dtype(
            dtype, self.n_samples, itemsize=super().dtype["samples"].base.itemsize
        )
        super(Distribution, self.__class__).dtype.__set__(self, dtype)

    def astype(self, dtype, *args, **kwargs):
        return Distribution(self.distribution.astype(dtype, *args, **kwargs))

    @staticmethod
    def _result_as_distribution(result):
        if isinstance(result, Distribution) or result is NotImplemented:
            return result
        if isinstance(result, (tuple, list)):
            result_cls = getattr(result, "_make", result.__class__)
            return result_cls(
                Distribution._result_as_distribution(item) for item in result
            )
        if isinstance(result, np.ndarray) and result.ndim:
            return Distribution(result)
        return result

    def __array_function__(self, function, types, args, kwargs):
        if function in DISTRIBUTION_SAFE_FUNCTIONS:
            return super().__array_function__(function, types, args, kwargs)

        if function in FUNCTION_HELPERS:
            try:
                args, kwargs, out = FUNCTION_HELPERS[function](*args, **kwargs)
            except NotImplementedError:
                return self._not_implemented_or_raise(function, types)
            result = function(*args, **kwargs)
            if out is not None:
                return out
            return self._result_as_distribution(result)

        if function in DISPATCHED_FUNCTIONS:
            try:
                return DISPATCHED_FUNCTIONS[function](*args, **kwargs)
            except NotImplementedError:
                return self._not_implemented_or_raise(function, types)

        if function in UNSUPPORTED_FUNCTIONS:
            return NotImplemented
        return super().__array_function__(function, types, args, kwargs)

    @staticmethod
    def _gufunc_core_dimensions(function, inputs):
        if function is np.matmul:
            first = min(2, inputs[0].ndim)
            second = min(2, inputs[1].ndim)
            return (first, second), (int(first == 2) + int(second == 2),)
        in_sig, out_sig = _parse_gufunc_signature(function.signature.replace(" ", ""))
        return tuple(map(len, in_sig)), tuple(map(len, out_sig))

    def __array_ufunc__(self, function, method, *inputs, **kwargs):
        if function.signature and "axes" in kwargs:
            raise NotImplementedError(
                "the axes keyword is not supported for Distribution generalized ufuncs"
            )

        distributions = [item for item in inputs if isinstance(item, Distribution)]
        if not distributions:
            return NotImplemented
        n_samples = distributions[0].n_samples
        if any(item.n_samples != n_samples for item in distributions[1:]):
            raise ValueError(
                "all Distribution inputs must have the same number of samples"
            )

        gufunc = bool(function.signature) and method == "__call__"
        if gufunc:
            in_core, out_core = self._gufunc_core_dimensions(function, inputs)
        else:
            in_core = (0,) * len(inputs)
            out_core = (0,) * function.nout

        def sample_array(value, core_ndim=0):
            if isinstance(value, Distribution):
                array = value.distribution
                if core_ndim:
                    array = np.moveaxis(array, -1, -1 - core_ndim)
                return array
            if isinstance(value, (np.ndarray, np.generic)) or np.isscalar(value):
                array = np.asanyarray(value)
                return np.expand_dims(array, array.ndim - core_ndim)
            return value

        if method in {"reduce", "accumulate", "reduceat"}:
            converted = [inputs[0].distribution, *inputs[1:]]
            logical_ndim = inputs[0].ndim
            if "axis" in kwargs:
                axis = kwargs["axis"]
                if axis is None:
                    if method == "accumulate":
                        converted[0] = converted[0].reshape(-1, n_samples)
                        kwargs["axis"] = 0
                    else:
                        kwargs["axis"] = tuple(range(logical_ndim))
                elif isinstance(axis, tuple):
                    kwargs["axis"] = tuple(
                        normalize_axis_index(a, logical_ndim) for a in axis
                    )
                else:
                    kwargs["axis"] = normalize_axis_index(axis, logical_ndim)
        elif method == "at":
            converted = [inputs[0].distribution, inputs[1]]
            if len(inputs) > 2:
                converted.append(sample_array(inputs[2]))
        else:
            converted = [
                sample_array(value, in_core[index] if gufunc else 0)
                for index, value in enumerate(inputs)
            ]

        matmul_optional = gufunc and function is np.matmul
        if matmul_optional:
            if in_core[0] == 1:
                converted[0] = np.expand_dims(converted[0], -2)
            if in_core[1] == 1:
                converted[1] = np.expand_dims(converted[1], -1)

        original_out = kwargs.get("out")
        if original_out is not None:
            converted_out = []
            for index, output in enumerate(original_out):
                if output is None:
                    converted_out.append(None)
                elif not isinstance(output, Distribution):
                    return NotImplemented
                else:
                    array = output.distribution
                    if gufunc and out_core[index]:
                        array = np.moveaxis(array, -1, -1 - out_core[index])
                    if matmul_optional:
                        if in_core[0] == 1:
                            array = np.expand_dims(array, -1 - out_core[index])
                        if in_core[1] == 1:
                            array = np.expand_dims(array, -1)
                    converted_out.append(array)
            kwargs["out"] = tuple(converted_out)

        where = kwargs.get("where", True)
        if isinstance(where, Distribution):
            kwargs["where"] = where.distribution
        elif where is not True and method in {"__call__", "reduce"}:
            kwargs["where"] = sample_array(where)

        result = getattr(function, method)(*converted, **kwargs)
        if result is None or result is NotImplemented:
            return result
        if original_out is not None:
            return original_out[0] if function.nout == 1 else original_out

        if matmul_optional:
            if in_core[0] == 1:
                result = np.squeeze(result, axis=-2)
            if in_core[1] == 1:
                result = np.squeeze(result, axis=-1)

        def wrap(value, core_ndim=0):
            if isinstance(value, np.ndarray):
                if gufunc and core_ndim:
                    value = np.moveaxis(value, -1 - core_ndim, -1)
                return Distribution(value)
            return value

        if isinstance(result, (tuple, list)):
            result_cls = getattr(result, "_make", result.__class__)
            return result_cls(
                wrap(value, out_core[index] if gufunc else 0)
                for index, value in enumerate(result)
            )
        return wrap(result, out_core[0] if gufunc else 0)
    def _not_implemented_or_raise(self, function, types):
        # Our function helper or dispatcher found that the function does not
        # work with Distribution.  In principle, there may be another class that
        # knows what to do with us, for which we should return NotImplemented.
        # But if there is ndarray (or a non-Distribution subclass of it) around,
        # it quite likely coerces, so we should just break.
        if any(
            issubclass(t, np.ndarray) and not issubclass(t, Distribution) for t in types
        ):
            raise TypeError(
                f"the Distribution implementation cannot handle {function} "
                "with the given arguments."
            ) from None
        else:
            return NotImplemented

    # Override __eq__ and __ne__ to pass on directly to the ufunc since
    # otherwise comparisons with non-distributions do not work (but
    # deferring if other defines __array_ufunc__ = None -- see
    # numpy/core/src/common/binop_override.h for the logic; we assume we
    # will never deal with __array_priority__ any more).  Note: there is no
    # problem for other comparisons, since for those, structured arrays are
    # not treated differently in numpy/core/src/multiarray/arrayobject.c.
    def __eq__(self, other):
        if getattr(other, "__array_ufunc__", False) is None:
            return NotImplemented
        return np.equal(self, other)

    def __ne__(self, other):
        if getattr(other, "__array_ufunc__", False) is None:
            return NotImplemented
        return np.not_equal(self, other)

    def pdf_std(self, dtype=None, out=None, ddof=0):
        """The standard deviation of this distribution."""
        return self.distribution.std(axis=-1, dtype=dtype, out=out, ddof=ddof)
    def pdf_mean(self, dtype=None, out=None):
        """
        The mean of this distribution.

        Arguments are as for `numpy.mean`.
        """
        return self.distribution.mean(axis=-1, dtype=dtype, out=out)

    def pdf_median(self, out=None):
        """The median of this distribution."""
        return np.median(self.distribution, axis=-1, out=out)
    def pdf_var(self, dtype=None, out=None, ddof=0):
        """
        The variance of this distribution.

        Arguments are as for `numpy.var`.
        """
        return self.distribution.var(axis=-1, dtype=dtype, out=out, ddof=ddof)
    def pdf_mad(self, out=None):
        """
        The median absolute deviation of this distribution.

        Parameters
        ----------
        out : array, optional
            Alternative output array in which to place the result. It must
            have the same shape and buffer length as the expected output,
            but the type (of the output) will be cast if necessary.
        """

        Returns
        -------
        hist : array
