"""Helpers for letting numpy functions interact with distributions.

The module supplies helper routines for numpy functions that propagate
distributions appropriately., for use in the ``__array_function__``
implementation of `~astropy.uncertainty.core.Distribution`.  They are not
very useful on their own, but the ones with docstrings are included in
the documentation so that there is a place to find out how the distributions
are interpreted.

"""

import numpy as np

from astropy.units.quantity_helper.function_helpers import FunctionAssigner

# This module should not really be imported, but we define __all__
# such that sphinx can typeset the functions with docstrings.
# The latter are added to __all__ at the end.
__all__ = [
    "DISPATCHED_FUNCTIONS",
    "DISTRIBUTION_SAFE_FUNCTIONS",
    "UNSUPPORTED_FUNCTIONS",
]


DISTRIBUTION_SAFE_FUNCTIONS = set()
"""Set of functions that work fine on Distribution classes already.

Most of these internally use `numpy.ufunc` or other functions that
are already covered.
"""

DISPATCHED_FUNCTIONS = {}
"""Dict of functions that provide the numpy function's functionality.

These are for more complicated versions where the numpy function itself
cannot easily be used.  It should return the result of the function.

It should raise `NotImplementedError` if one of the arguments is a
distribution when it should not be or vice versa.
"""


FUNCTION_HELPERS = {}
"""Dict of functions for which Distribution can be used after some conversions.

The `dict` is keyed by the numpy function and the values are functions
that take the input arguments of the numpy function and organize these
for passing the distribution data to the numpy function, by returning
``args, kwargs, out``. Here, the former two are passed on, while ``out``
is used to indicate whether there was an output argument.  If ``out`` is
set to `True`, then no further processing should be done; otherwise, it
it is assumed that the function operates on unwrapped distributions and
that the results need to be rewrapped as |Distribution|.

The function should raise `NotImplementedError` if one of the arguments is a
distribution when it should not be or vice versa.

"""


UNSUPPORTED_FUNCTIONS = set()
"""Set of numpy functions that are not supported for distributions.

For most, distributions simply make no sense, but for others it may have
been lack of time.  Issues or PRs for support for functions are welcome.
"""


function_helper = FunctionAssigner(FUNCTION_HELPERS)
dispatched_function = FunctionAssigner(DISPATCHED_FUNCTIONS)


def _distribution_type():
    # Import lazily: core imports the registries in this module.
    from .core import Distribution

    return Distribution


def _common_n_samples(arrays):
    Distribution = _distribution_type()
    counts = {array.n_samples for array in arrays if isinstance(array, Distribution)}
    if not counts:
        raise NotImplementedError
    if len(counts) != 1:
        raise ValueError("all Distribution inputs must have the same number of samples")
    return counts.pop()


@dispatched_function
def empty_like(
    prototype, dtype=None, order="K", subok=True, shape=None, *, device=None
):
    """Create an empty Distribution with the same number of samples."""
    Distribution = _distribution_type()
    if not isinstance(prototype, Distribution):
        raise NotImplementedError

    sample_shape = prototype.distribution.shape
    if shape is not None:
        if np.isscalar(shape):
            shape = (shape,)
        else:
            shape = tuple(shape)
        sample_shape = shape + (prototype.n_samples,)

    kwargs = {
        "dtype": dtype,
        "order": order,
        "subok": subok,
        "shape": sample_shape,
    }
    if device is not None:
        kwargs["device"] = device
    return Distribution(np.empty_like(prototype.distribution, **kwargs))


@dispatched_function
def broadcast_to(array, shape, subok=False):
    """Broadcast logical Distribution axes while retaining the sample axis."""
    Distribution = _distribution_type()
    if not isinstance(array, Distribution):
        raise NotImplementedError
    if np.isscalar(shape):
        shape = (shape,)
    result = np.broadcast_to(
        array.distribution, tuple(shape) + (array.n_samples,), subok=subok
    )
    return Distribution(result)


@dispatched_function
def broadcast_arrays(*args, subok=False):
    """Broadcast Distribution and ordinary inputs over their logical shapes."""
    Distribution = _distribution_type()
    n_samples = _common_n_samples(args)
    shape = np.broadcast_shapes(*(arg.shape for arg in args))
    result = []
    for arg in args:
        if isinstance(arg, Distribution):
            samples = np.broadcast_to(
                arg.distribution, shape + (n_samples,), subok=subok
            )
            result.append(Distribution(samples))
        else:
            result.append(np.broadcast_to(arg, shape, subok=subok))
    return result


@dispatched_function
def concatenate(
    arrays, axis=0, out=None, *, dtype=None, casting="same_kind"
):
    """Concatenate logical Distribution axes, repeating ordinary inputs."""
    Distribution = _distribution_type()
    arrays = tuple(arrays)
    n_samples = _common_n_samples(arrays)

    sample_arrays = []
    for array in arrays:
        if isinstance(array, Distribution):
            sample_arrays.append(array.distribution)
        else:
            array = np.asanyarray(array)
            sample_arrays.append(
                np.broadcast_to(
                    array[..., np.newaxis], array.shape + (n_samples,), subok=True
                )
            )

    if axis is None:
        sample_arrays = [a.reshape(-1, n_samples) for a in sample_arrays]
        sample_axis = 0
    else:
        logical_ndim = sample_arrays[0].ndim - 1
        sample_axis = axis + logical_ndim if axis < 0 else axis
        if sample_axis < 0 or sample_axis >= logical_ndim:
            raise np.exceptions.AxisError(axis, ndim=logical_ndim)

    out_samples = None
    if out is not None:
        if not isinstance(out, Distribution) or out.n_samples != n_samples:
            raise NotImplementedError
        out_samples = out.distribution

    kwargs = {"axis": sample_axis, "out": out_samples, "casting": casting}
    if dtype is not None:
        kwargs["dtype"] = dtype
    result = np.concatenate(sample_arrays, **kwargs)
    return out if out is not None else Distribution(result)

# Add any dispatched or helper function that has a docstring to __all__, so
# they will be typeset by sphinx. The logic is that for those presumably the
# way distributions are dealt with is not entirely obvious.
__all__ += sorted(  # noqa: PLE0605
    helper.__name__
    for helper in (set(FUNCTION_HELPERS.values()) | set(DISPATCHED_FUNCTIONS.values()))
    if helper.__doc__
)
